/* sonar_edge: integer-only single-stage sonar debris detector, C11, no dependencies.
 *
 * The network, its weights and all tensor shapes are compiled in (weights.h,
 * generated by sonar_edge.export_c). Inference uses only integer arithmetic;
 * the decoder uses a few float operations to turn integer head outputs into
 * scores and pixel boxes. Static working memory; not thread-safe.
 */
#pragma once
#include <stddef.h>
#include <stdint.h>

typedef struct {
    int cls;        /* class index, 0..SE_N_CLASSES-1 */
    float score;    /* logit (monotone in probability); sigmoid(score) is the confidence */
    float x0, y0, x1, y1;  /* box in input pixels (working resolution) */
} se_detection_t;

/* Input geometry (from weights.h). */
int se_input_height(void);
int se_input_width(void);
int se_num_classes(void);

/* Run the network on one frame (row-major uint8, se_input_height() x
 * se_input_width()) and decode detections with logit >= thr into out[].
 * Returns the number of detections written (<= max_out), sorted by score
 * descending. */
int se_detect(const uint8_t *frame, float thr, se_detection_t *out, int max_out);

/* Run only the network. Returns the int32 head map, HWC
 * [SE_OUT_H][SE_OUT_W][SE_HEAD_COUT]. Valid until the next call. */
const int32_t *se_forward(const uint8_t *frame);
int se_out_height(void);
int se_out_width(void);
int se_head_channels(void);

/* Semantic segmentation (models exported with a segmentation head, M6).
 * se_seg_classes() is the number of labels (0 = background, c + 1 =
 * detector class c), or 0 when the compiled-in model has none; se_seg_up()
 * is the label grid's refinement over the output grid (1, or 2 for the
 * sub-pixel head). se_segment() runs the network and writes one label per
 * label cell to labels[] (row-major, se_seg_height() x se_seg_width());
 * upsample by stride / se_seg_up() to get a working-resolution mask.
 * Returns the number of cells written, or -1 when the model has no head.
 * se_segment_head() does the same from a head map returned by se_forward(),
 * so boxes and labels can share one forward pass. */
int se_seg_classes(void);
int se_seg_up(void);
int se_seg_height(void);
int se_seg_width(void);
int se_segment(const uint8_t *frame, uint8_t *labels);
int se_segment_head(const int32_t *head, uint8_t *labels);
